function maxFrequencyElements(nums) {
  const count = new Map();
  let maxFreq = 0;
  let total = 0;
  for (const num of nums) {
    const freq = (count.get(num) || 0) + 1;
    count.set(num, freq);
    if (freq > maxFreq) {
      maxFreq = freq;
      total = freq;
    } else if (freq === maxFreq) {
      total += freq;
    }
  }
  return total;
}

